function readSWFLength(bytes) {
    // We read the length manually because creating a DataView just for that is silly.
    return (bytes[4] | bytes[5] << 8 | bytes[6] << 16 | bytes[7] << 24) >>> 0;
}
function defineSymbol(swfTag, symbols, parser) {
    var noRec = true;
    var d = noRec ? null : Stat.rec('parser').rec('symbols').rec('define');
    var rec;
    var ret;
    switch (swfTag.code) {
        case 6 /* SwfTagCode.CODE_DEFINE_BITS */:
        case 21 /* SwfTagCode.CODE_DEFINE_BITS_JPEG2 */:
        case 35 /* SwfTagCode.CODE_DEFINE_BITS_JPEG3 */:
        case 90 /* SwfTagCode.CODE_DEFINE_BITS_JPEG4 */:
            {
                if (!noRec) {
                    rec = d.rec('image');
                    rec.begin();
                }
                ret = defineImage(swfTag);
                break;
            }
        case 20 /* SwfTagCode.CODE_DEFINE_BITS_LOSSLESS */:
        case 36 /* SwfTagCode.CODE_DEFINE_BITS_LOSSLESS2 */:
            {
                if (!noRec) {
                    rec = d.rec('bitmap');
                    rec.begin();
                }
                ret = defineBitmap(swfTag);
                break;
            }
        case 7 /* SwfTagCode.CODE_DEFINE_BUTTON */:
        case 34 /* SwfTagCode.CODE_DEFINE_BUTTON2 */:
            {
                if (!noRec) {
                    rec = d.rec('button');
                    rec.begin();
                }
                ret = defineButton(swfTag, symbols);
                break;
            }
        case 37 /* SwfTagCode.CODE_DEFINE_EDIT_TEXT */:
            {
                if (!noRec) {
                    rec = d.rec('text');
                    rec.begin();
                }
                ret = defineText(swfTag);
                break;
            }
        case 10 /* SwfTagCode.CODE_DEFINE_FONT */:
        case 48 /* SwfTagCode.CODE_DEFINE_FONT2 */:
        case 75 /* SwfTagCode.CODE_DEFINE_FONT3 */:
        case 91 /* SwfTagCode.CODE_DEFINE_FONT4 */:
            {
                if (!noRec) {
                    rec = d.rec('font');
                    rec.begin();
                }
                ret = defineFont(swfTag, parser.fileName);
                break;
            }
        case 46 /* SwfTagCode.CODE_DEFINE_MORPH_SHAPE */:
        case 84 /* SwfTagCode.CODE_DEFINE_MORPH_SHAPE2 */:
        case 2 /* SwfTagCode.CODE_DEFINE_SHAPE */:
        case 22 /* SwfTagCode.CODE_DEFINE_SHAPE2 */:
        case 32 /* SwfTagCode.CODE_DEFINE_SHAPE3 */:
        case 83 /* SwfTagCode.CODE_DEFINE_SHAPE4 */:
            {
                if (!noRec) {
                    rec = d.rec('shape');
                    rec.begin();
                }
                ret = defineShape(swfTag, parser.factory);
                break;
            }
        case 14 /* SwfTagCode.CODE_DEFINE_SOUND */:
            {
                if (!noRec) {
                    rec = d.rec('sound');
                    rec.begin();
                }
                ret = defineSound(swfTag);
                break;
            }
        case 60 /* SwfTagCode.CODE_DEFINE_VIDEO_STREAM */:
            return {
                type: "video" /* SYMBOL_TYPE.VIDEO */,
                id: swfTag.id,
                width: swfTag.width,
                height: swfTag.height,
                deblocking: swfTag.deblocking,
                smoothing: swfTag.smoothing,
                codec: swfTag.codecId
            };
        case 39 /* SwfTagCode.CODE_DEFINE_SPRITE */:
            // Sprites are fully defined at this point.
            return swfTag;
        case 87 /* SwfTagCode.CODE_DEFINE_BINARY_DATA */:
            return {
                type: "binary" /* SYMBOL_TYPE.BINARY */,
                id: swfTag.id,
                data: swfTag.data
            };
        case 11 /* SwfTagCode.CODE_DEFINE_TEXT */:
        case 33 /* SwfTagCode.CODE_DEFINE_TEXT2 */:
            {
                if (!noRec) {
                    rec = d.rec('label');
                    rec.begin();
                }
                ret = defineLabel(swfTag);
                break;
            }
        default:
            //console.log("define default symbol", swfTag, symbols, parser);
            return swfTag;
    }
    noRec || rec.end();
    return ret;
}
